curl -X POST https://api.zsapi.net/event-monitoring/subscriptions \
	-H "Authorization: Bearer <Token>" \
	-H "Content-Type: application/json" \
	-H "x-em-cloud: prod.zpath.net" \
	-H "x-em-tenant: 145254691217866752" \
	-d '{
	"name": "ZPA Connector Status Down",
	"description": "Get notified when a ZPA connector goes down",
	"scope": {
		"source_key": "zpa",
		"source_type_key": "app_connector",
		"source_event_key": "status"
	},
	"channels": [
		{
		"type": "email",
		"email": {
			"to": ["admin@example.com"],
			"cc": ["team@example.com"],
			"bcc": []
		}
		}
	],
	"enabled": true
	}'

curl -X POST https://api.zsapi.net/event-monitoring/subscriptions \
	-H "Authorization: Bearer <Token>" \
	-H "Content-Type: application/json" \
	-H "x-em-cloud: prod.zpath.net" \
	-H "x-em-tenant: 145254691217866752" \
	-d '{
	"name": "ZPA Connector Alerts - Webhook",
	"description": "Send connector alerts to our webhook",
	"scope": {
		"source_key": "zpa",
		"source_type_key": "app_connector",
		"source_event_key": "status"
	},
	"channels": [
		{
		"type": "webhook",
		"webhook_url": "https://hooks.example.com/em-alerts"
		}
	],
	"enabled": true
	}'

{
  "channels": [
    {
      "type": "email",
      "description": "Email notifications",
      "setup_required": false,
      "_links": { "self": "/subscriptions/channels/email" }
    },
    {
      "type": "webhook",
      "description": "Webhook notifications",
      "setup_required": false,
      "_links": { "self": "/subscriptions/channels/webhook" }
    },
    {
      "type": "sns",
      "description": "AWS SNS topic notifications",
      "setup_required": true,
      "_links": {
        "self": "/subscriptions/channels/sns",
        "verify": "/subscriptions/channels/sns:verify"
      }
    }
  ]
}

POST /subscriptions HTTP/1.1
Host: api.zsapi.net
Authorization: Bearer <access-token>
Content-Type: application/json

{
  "name": "ZPA App Connector Status to SNS",
  "description": "Forward ZPA App Connector UP/DOWN events to my SNS topic",
  "scope": {
    "source_key": "zpa",
    "source_type_key": "app_connector",
    "source_event_key": "status"
  },
  "channels": [
    {
      "type": "sns",
      "topic_arn": "arn:aws:sns:us-west-2:123456789012:zscaler-em-events",
      "region": "us-west-2"
    }
  ],
  "enabled": true
}
